class Solution {
    public ListNode partition(ListNode head, int x) {
        ListNode lessHead = new ListNode(0);
        ListNode greaterHead = new ListNode(0);
        ListNode less = lessHead, greater = greaterHead;

        while (head != null) {
            if (head.val < x) {
                less.next = head;
                less = less.next;
            } else {
                greater.next = head;
                greater = greater.next;
            }
            head = head.next;
        }

        greater.next = null;
        less.next = greaterHead.next;

        return lessHead.next;
    }
}

class Solution {
    public ListNode partition(ListNode head, int x) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;

        // Find the last node in the 'less than x' section
        ListNode lastSmall = dummy;
        // First, advance lastSmall past any initial nodes < x
        while (lastSmall.next != null && lastSmall.next.val < x) {
            lastSmall = lastSmall.next;
        }

        // Now scan the rest, moving nodes < x to after lastSmall
        ListNode prev = lastSmall;
        while (prev.next != null) {
            if (prev.next.val < x) {
                // Detach node
                ListNode node = prev.next;
                prev.next = node.next;
                // Insert after lastSmall
                node.next = lastSmall.next;
                lastSmall.next = node;
                lastSmall = node;
            } else {
                prev = prev.next;
            }
        }

        return dummy.next;
    }
}
